mapper.sql:
task.tenant_id = #{tenantId} AND task.deleted = 0 AND (
OR (#{scope.selfData} = 1 AND ( task.assignee_user_id = #{scope.userId} OR EXISTS ( SELECT 1 FROM inspection_task_assignee scoped_assignee WHERE scoped_assignee.tenant_id = task.tenant_id AND scoped_assignee.task_id = task.id AND scoped_assignee.user_id = #{scope.userId} AND scoped_assignee.deleted = 0 ) )) )
AND (task.task_code LIKE CONCAT('%', #{query.keyword}, '%') OR task.scheme_name_snapshot LIKE CONCAT('%', #{query.keyword}, '%') OR e.equipment_code LIKE CONCAT('%', #{query.keyword}, '%') OR e.equipment_name LIKE CONCAT('%', #{query.keyword}, '%') OR task.team_code LIKE CONCAT('%', #{query.keyword}, '%') OR EXISTS ( SELECT 1 FROM inspection_task_assignee searched_assignee JOIN system_user searched_user ON searched_user.tenant_id = searched_assignee.tenant_id AND searched_user.id = searched_assignee.user_id AND searched_user.deleted = 0 WHERE searched_assignee.tenant_id = task.tenant_id AND searched_assignee.task_id = task.id AND searched_assignee.deleted = 0 AND ( searched_user.real_name LIKE CONCAT('%', #{query.keyword}, '%') OR searched_user.username LIKE CONCAT('%', #{query.keyword}, '%') ) ))
AND task.task_status = #{query.taskStatus}
AND task.task_status IN ('PENDING', 'OVERDUE')
AND task.task_status = 'IN_PROGRESS'
AND task.task_status IN ('COMPLETED', 'PENDING_REVIEW')
AND task.task_status IN ('PENDING', 'IN_PROGRESS', 'OVERDUE') AND task.assignee_user_id IS NULL AND NOT EXISTS ( SELECT 1 FROM inspection_task_assignee dispatch_assignee WHERE dispatch_assignee.tenant_id = task.tenant_id AND dispatch_assignee.task_id = task.id AND dispatch_assignee.deleted = 0 )
AND task.task_status = 'PENDING' AND COALESCE(task.planned_start_time, TIMESTAMP(task.planned_date)) > CURRENT_TIMESTAMP(3) AND ( task.assignee_user_id IS NOT NULL OR EXISTS ( SELECT 1 FROM inspection_task_assignee dispatch_assignee WHERE dispatch_assignee.tenant_id = task.tenant_id AND dispatch_assignee.task_id = task.id AND dispatch_assignee.deleted = 0 ) )
AND task.task_status IN ('PENDING', 'IN_PROGRESS', 'OVERDUE') AND ( task.assignee_user_id IS NOT NULL OR EXISTS ( SELECT 1 FROM inspection_task_assignee dispatch_assignee WHERE dispatch_assignee.tenant_id = task.tenant_id AND dispatch_assignee.task_id = task.id AND dispatch_assignee.deleted = 0 ) ) AND ( task.task_status != 'PENDING' OR COALESCE(task.planned_start_time, TIMESTAMP(task.planned_date)) <= CURRENT_TIMESTAMP(3) )
AND task.task_status IN ('COMPLETED', 'PENDING_REVIEW')
AND task.planned_date = #{query.plannedDate}
AND task.started_time >= #{query.startDate}
AND task.submitted_time >= #{query.startDate}
AND task.completed_time >= #{query.startDate}
AND task.planned_date >= #{query.startDate}
AND task.started_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
AND task.submitted_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
AND task.completed_time < DATE_ADD(#{query.endDate}, INTERVAL 1 DAY)
AND task.planned_date <= #{query.endDate}
AND task.organization_id = #{query.organizationId}
AND task.team_code = #{query.teamCode}
AND ( task.assignee_user_id = #{query.assigneeUserId} OR EXISTS ( SELECT 1 FROM inspection_task_assignee filtered_assignee WHERE filtered_assignee.tenant_id = task.tenant_id AND filtered_assignee.task_id = task.id AND filtered_assignee.user_id = #{query.assigneeUserId} AND filtered_assignee.deleted = 0 ) )
AND task.equipment_id = #{query.equipmentId} AND task.scheme_id = #{query.schemeId}
AND EXISTS ( SELECT 1 FROM inspection_task_result abnormal_result WHERE abnormal_result.tenant_id = task.tenant_id AND abnormal_result.task_id = task.id AND abnormal_result.deleted = 0 AND abnormal_result.abnormal_flag = 1 )
AND EXISTS ( SELECT 1 FROM inspection_abnormal filtered_abnormal WHERE filtered_abnormal.tenant_id = task.tenant_id AND filtered_abnormal.task_id = task.id AND filtered_abnormal.deleted = 0 AND filtered_abnormal.severity = #{query.abnormalSeverity} )
AND ( task.assignee_user_id = #{scope.userId} OR EXISTS ( SELECT 1 FROM inspection_task_assignee mine_assignee WHERE mine_assignee.tenant_id = task.tenant_id AND mine_assignee.task_id = task.id AND mine_assignee.user_id = #{scope.userId} AND mine_assignee.deleted = 0 ) )

