SELECT file.id, file.export_job_id, file.file_name, file.storage_path,
       file.content_type, file.file_size, file.sha256
FROM inspection_export_file file
JOIN inspection_export_job job ON job.id = file.export_job_id
WHERE file.tenant_id = #{tenantId}
  AND file.export_job_id = #{jobId}
  AND file.id = #{fileId}
  AND job.tenant_id = file.tenant_id
  AND job.requested_by = #{requestedBy}
  AND job.job_status = 'COMPLETED'
LIMIT 1

