UPDATE inspection_attachment SET deleted = 1
WHERE tenant_id = #{tenantId} AND task_result_id = #{taskResultId}
  AND deleted = 0

UPDATE inspection_attachment SET deleted = 1
WHERE tenant_id = #{tenantId}
  AND task_id = #{taskId}
  AND task_result_id IS NULL
  AND attachment_type = 'TASK_PHOTO'
  AND deleted = 0

mapper.select:
SELECT COUNT(*)
FROM inspection_attachment relation
JOIN system_attachment attachment
  ON attachment.tenant_id = relation.tenant_id
 AND attachment.id = relation.attachment_id
 AND attachment.deleted = 0
WHERE relation.tenant_id = #{tenantId}
  AND relation.task_id = #{taskId}
  AND relation.attachment_id = #{attachmentId}
  AND relation.deleted = 0

mapper.insert:
INSERT INTO inspection_task_assignee
    (tenant_id, task_id, user_id, primary_flag, sort_order, created_by)
SELECT relation.tenant_id, #{taskId}, relation.user_id,
       relation.primary_flag, relation.sort_order, #{operatorId}
FROM inspection_scheme_default_assignee relation
WHERE relation.tenant_id = #{tenantId}
  AND relation.scheme_version_id = #{schemeVersionId}
ORDER BY relation.sort_order, relation.id

