mapper.update:
UPDATE inspection_task
SET task_status = #{targetStatus},
    cancel_reason = CASE WHEN #{targetStatus} = 'CANCELLED' THEN #{request.reason}
                         ELSE cancel_reason END,
    void_reason = CASE WHEN #{targetStatus} = 'VOIDED' THEN #{request.reason}
                       ELSE void_reason END,
    updated_by = #{operatorId}, version = version + 1
WHERE tenant_id = #{tenantId} AND id = #{id} AND deleted = 0
  AND version = #{request.version}
  AND task_status NOT IN ('COMPLETED','CANCELLED','VOIDED')

