SELECT 
FROM inspection_abnormal abnormal

WHERE abnormal.tenant_id = #{tenantId} AND abnormal.id = #{id}
  AND abnormal.deleted = 0
  AND (

    OR (#{scope.selfData} = 1 AND (
        abnormal.responsible_user_id = #{scope.userId}
